/* prog21_date_validator.c
 * Reimplementation of the original obfuscated binary.
 * The program expects exactly one command‑line argument:
 *   YYYY-MM-DD
 * It prints "VALID" if the argument is a correct Gregorian calendar date,
 * otherwise it prints "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

/* Return 1 if the given year is a leap year in the Gregorian calendar. */
static int is_leap_year(int year)
{
    /* Leap year if divisible by 4, but not by 100 unless also by 400 */
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

/* Return the number of days in the given month of the given year.
 * month is 1‑based (1 = January). */
static int days_in_month(int year, int month)
{
    static const int days[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    if (month < 1 || month > 12)
        return 0;               /* invalid month */

    if (month == 2 && is_leap_year(year))
        return 29;

    return days[month - 1];
}

/* Validate the date string. Returns 1 for a valid date, 0 otherwise. */
static int validate_date(const char *s)
{
    /* Length must be exactly 10 characters: YYYY-MM-DD */
    if (strlen(s) != 10)
        return 0;

    /* Positions 4 and 7 must be '-' */
    if (s[4] != '-' || s[7] != '-')
        return 0;

    /* All other characters must be decimal digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!isdigit((unsigned char)s[i]))
            return 0;
    }

    /* Convert the three fields */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Basic range checks */
    if (month < 1 || month > 12)
        return 0;
    if (day < 1)
        return 0;

    /* Day must not exceed the number of days in the month */
    if (day > days_in_month(year, month))
        return 0;

    /* All checks passed */
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
